\"\"\"Send private text prompts to the OpenAI Responses API with the standard library.

Official request shape (could not be re-fetched: developers.openai.com and
platform.openai.com did not resolve in this environment):

- POST https://api.openai.com/v1/responses
- JSON body fields used here: model, input, optional instructions,
  optional max_output_tokens, and store
- Authorization: Bearer API key

"'``store`` is always false. That asks the API not to retain the response for
later retrieval. This module does not log prompt text or credentials, and
exception messages omit the prompt and redact key-like substrings.

Account-level abuse-monitoring retention and zero-data-retention eligibility
are not request parameters. Those policies were not re-verified against the
current official privacy page because the network was unreachable.
"""

from __future__ import annotations

import json
import os
import re
import ssl
import urllib.error
import urllib.request
from typing import Any, Mapping

DEFAULT_BASE_URL = "https://api.openai.com/v1"
_RESPONSES_PATH = "/responses"
_KEY_RE = re.compile(r"(sk-|sess-|ek-)[A-Za-z0-9_'"\\-]{6,}\")
_BEARER_RE = re.compile(r\"Bearer\\s+\\S+\", re.IGNORECASE)
_MAX_ERROR_CHARS = 500


class OpenAIError(Exception):
    \"\"\"Responses API failure that does not include the prompt.\"\"\"


class _RejectRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        raise OpenAIError(\"refusing redirect while calling the Responses API\")


def send_text(
    prompt: str,
    model: str | None = None,
    *,
    instructions: str | None = None,
    api_key: str | None = None,
    base_url: str | None = None,
    timeout: float = 120.0,
    max_output_tokens: int | None = None,
) -> str:
    \"\"\"Send one private text prompt and return the assistant text.

    "'``model`` defaults to the ``OPENAI_MODEL`` environment variable.
    ``api_key`` defaults to ``OPENAI_API_KEY``. ``base_url`` defaults to
    ``OPENAI_BASE_URL`` or ``https://api.openai.com/v1``.
    """
    payload = create_response(
        prompt,
        model,
        instructions=instructions,
        api_key=[REDACTED_SECRET]
        base_url=base_url,
        timeout=timeout,
        max_output_tokens=max_output_tokens,
    )
    return output_text(payload)


def create_response(
    prompt: str,
    model: str | None = None,
    *,
    instructions: str | None = None,
    api_key: str | None = None,
    base_url: str | None = None,
    timeout: float = 120.0,
    max_output_tokens: int | None = None,
) -> dict[str, Any]:
    """POST a text prompt to ``/responses`` and return the parsed JSON object."""
    text = _require_text(prompt, "prompt")
    chosen_model = _require_model(model)
    key = _require_api_key(api_key)
    url = _responses_url(base_url)
    body: dict[str, Any] = {
        "model": chosen_model,
        "input": text,
        "store": False,
    }
    if instructions is not None:
        body["instructions"] = _require_text(instructions, "instructions")
    if max_output_tokens is not None:
        if isinstance(max_output_tokens, bool) or not isinstance(max_output_tokens, int):
            raise OpenAIError("max_output_tokens must be an integer")
        if max_output_tokens < 1:
            raise OpenAIError("max_output_tokens must be positive")
        body["max_output_tokens"] = max_output_tokens
    return _post_json(url, body, key, timeout)


def output_text(payload: Mapping[str, Any]) -> str:
    """Collect assistant text from a Responses API JSON object."""
    status = payload.get("status")
    if status not in (None, "completed"):
        reason = _incomplete_reason(payload)
        detail = f"response status is {status}"
        if reason:
            detail = f"{detail} ({reason})"
        raise OpenAIError(detail)

    direct = payload.get("output_text")
    if isinstance(direct, str) and direct:
        return direct

    chunks: list[str] = []
    refusals: list[str] = []
    output = payload.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, Mapping):
                continue
            _collect_text(item, chunks, refusals)
            content = item.get("content")
            if isinstance(content, list):
                for part in content:
                    if isinstance(part, Mapping):
                        _collect_text(part, chunks, refusals)
            elif isinstance(content, str):
                chunks.append(content)
    if chunks:
        return "".join(chunks)
    if refusals:
        raise OpenAIError("model refused the prompt")
    if status == "completed":
        return ""
    raise OpenAIError("response did not include assistant text")


def _collect_text(part: Mapping[str, Any], chunks: list[str], refusals: list[str]) -> None:
    part_type = part.get("type")
    if part_type in {"output_text", "text"} and isinstance(part.get("text"), str):
        chunks.append(part["text"])
    elif part_type == "refusal" and isinstance(part.get("refusal"), str):
        refusals.append(part["refusal"])


def _incomplete_reason(payload: Mapping[str, Any]) -> str:
    details = payload.get("incomplete_details")
    if isinstance(details, Mapping) and isinstance(details.get("reason"), str):
        return details["reason"]
    error = payload.get("error")
    if isinstance(error, Mapping) and isinstance(error.get("message"), str):
        return _redact(error["message"])[:_MAX_ERROR_CHARS]
    return ""


def _post_json(url: str, body: Mapping[str, Any], api_key: str, timeout: float) -> dict[str, Any]:
    data = json.dumps(body, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        url,
        data=data,
        method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    opener = urllib.request.build_opener(
        _RejectRedirect,
        urllib.request.HTTPSHandler(context=ssl.create_default_context()),
    )
    try:
        with opener.open(request, timeout=timeout) as response:
            raw = response.read()
    except urllib.error.HTTPError as exc:
        detail = _http_error_detail(exc)
        raise OpenAIError(detail) from None
    except OpenAIError:
        raise
    except Exception:
        raise OpenAIError("network error contacting the Responses API") from None

    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError):
        raise OpenAIError("Responses API returned non-JSON data") from None
    if not isinstance(parsed, dict):
        raise OpenAIError("Responses API returned an unexpected JSON type")
    if isinstance(parsed.get("error"), Mapping):
        message = parsed["error"].get("message")
        if not isinstance(message, str) or not message:
            message = "Responses API returned an error"
        raise OpenAIError(_redact(message)[:_MAX_ERROR_CHARS])
    return parsed


def _http_error_detail(exc: urllib.error.HTTPError) -> str:
    message = ""
    try:
        raw = exc.read()
        parsed = json.loads(raw.decode("utf-8"))
        if isinstance(parsed, dict) and isinstance(parsed.get("error"), dict):
            candidate = parsed["error"].get("message")
            if isinstance(candidate, str):
                message = candidate
    except Exception:
        message = ""
    if not message:
        message = "Responses API request failed"
    return f"HTTP {exc.code}: {_redact(message)[:_MAX_ERROR_CHARS]}"


def _redact(text: str) -> str:
    text = _BEARER_RE.sub("Bearer ***", text)
    return _KEY_RE.sub(r"'"\\1***\", text)


def _require_text(value: str, name: str) -> str:
    if not isinstance(value, str):
        raise OpenAIError(f\"{name} must be a string\")
    if value == \"\":
        raise OpenAIError(f\"{name} must not be empty\")
    return value


def _require_model(model: str | None) -> str:
    chosen = model if model is not None else os.environ.get(\"OPENAI_MODEL\")
    if not isinstance(chosen, str) or not chosen.strip():
        raise OpenAIError(\"model is required; pass model or set OPENAI_MODEL\")
    return chosen.strip()


def _require_api_key(api_key: str | None) -> str:
    key = api_key if api_key is not None else os.environ.get(\"OPENAI_API_KEY\")
    if not isinstance(key, str) or not key.strip():
        raise OpenAIError(\"API key is required; pass api_key or set OPENAI_API_KEY\")
    return key.strip()


def _responses_url(base_url: str | None) -> str:
    base = base_url if base_url is not None else os.environ.get(\"OPENAI_BASE_URL\")
    if base is None or not str(base).strip():
        base = DEFAULT_BASE_URL
    base = str(base).strip().rstrip(\"/\")
    if not base.lower().startswith(\"https://\"):
        raise OpenAIError(\"base_url must use https\")
    if base.endswith(_RESPONSES_PATH):
        return base
    return f\"{base}{_RESPONSES_PATH}\"
EOF"

